/// The attributes a shader declares, or an empty slice for one with no table.
///
/// An empty table is not the same as a shader that binds nothing: it means this
/// build has no data for it, and a producer should treat that as a fault rather than
/// as permission to bind nothing.
#[must_use]
pub fn attributes(shader: BuiltIn) -> &'static [ShaderAttribute] {
    match shader {
        BuiltIn::BackgroundPatternShader => &BACKGROUND_PATTERN_SHADER,
        BuiltIn::BackgroundShader => &BACKGROUND_SHADER,
        BuiltIn::CircleShader => &CIRCLE_SHADER,
        BuiltIn::ClippingMaskProgram => &CLIPPING_MASK_PROGRAM,
        BuiltIn::CollisionBoxShader => &COLLISION_BOX_SHADER,
        BuiltIn::CollisionCircleShader => &COLLISION_CIRCLE_SHADER,
        BuiltIn::ColorReliefShader => &COLOR_RELIEF_SHADER,
        BuiltIn::CustomGeometryShader => &CUSTOM_GEOMETRY_SHADER,
        BuiltIn::CustomSymbolIconShader => &CUSTOM_SYMBOL_ICON_SHADER,
        BuiltIn::DebugShader => &DEBUG_SHADER,
        BuiltIn::FillExtrusionPatternShader => &FILL_EXTRUSION_PATTERN_SHADER,
        BuiltIn::FillExtrusionShader => &FILL_EXTRUSION_SHADER,
        BuiltIn::FillOutlinePatternShader => &FILL_OUTLINE_PATTERN_SHADER,
        BuiltIn::FillOutlineShader => &FILL_OUTLINE_SHADER,
        BuiltIn::FillPatternShader => &FILL_PATTERN_SHADER,
        BuiltIn::FillShader => &FILL_SHADER,
        BuiltIn::HeatmapShader => &HEATMAP_SHADER,
        BuiltIn::HeatmapTextureShader => &HEATMAP_TEXTURE_SHADER,
        BuiltIn::HillshadePrepareShader => &HILLSHADE_PREPARE_SHADER,
        BuiltIn::HillshadeShader => &HILLSHADE_SHADER,
        BuiltIn::LineGradientShader => &LINE_GRADIENT_SHADER,
        BuiltIn::LinePatternShader => &LINE_PATTERN_SHADER,
        BuiltIn::LineSDFShader => &LINE_SDFSHADER,
        BuiltIn::LineShader => &LINE_SHADER,
        BuiltIn::LocationIndicatorShader => &LOCATION_INDICATOR_SHADER,
        BuiltIn::RasterShader => &RASTER_SHADER,
        BuiltIn::SymbolIconShader => &SYMBOL_ICON_SHADER,
        BuiltIn::SymbolSDFShader => &SYMBOL_SDFSHADER,
        BuiltIn::SymbolTextAndIconShader => &SYMBOL_TEXT_AND_ICON_SHADER,
        BuiltIn::WideVectorShader => &WIDE_VECTOR_SHADER,
        _ => &[],
    }
}

/// Looks up what a shader declares for an attribute id.
///
/// `None` when the shader does not declare it. That is not an error: a drawable may
/// supply an override its shader has no slot for, and the rule is to bind it at -1 so
/// the consumer drops it (§2.2). `fill-outline-color` on the plain fill shader is
/// exactly that, and the golden dump shows it as `bind=-1 ddt=255`.
#[must_use]
pub fn declared_for(shader: BuiltIn, attr_id: u32) -> Option<ShaderAttribute> {
    attributes(shader)
        .iter()
        .find(|attribute| attribute.attr_id == attr_id)
        .copied()
}
